What will be the output of the following JavaScript code ?
<html>
<body>
<script>
var colors = ['Red', 'Blue', 'Green'];
document.write(colors.pop() + "<br>");
document.write(colors.push('Yellow') + "<br>");
document.write(colors.join('&') + "<br>");
document.write(colors.slice(1, 3));
</script>
</body>
</html>
